"""Regenerate src/glyph-names.js: Unicode names for every glyph the selector offers.

Browsers expose no Unicode character-name API, so the names are baked in from
Python's unicodedata. Run from the repo root after changing src/glyphs.js:

    python3 scripts/gen-glyph-names.py
"""
import json
import subprocess
import unicodedata

glyphs = json.loads(
    subprocess.check_output(
        ['node', '--input-type=module', '-e',
         "import { allGlyphs } from './src/glyphs.js'; console.log(JSON.stringify(allGlyphs()));"]
    )
)

lines = [
    '// Generated by scripts/gen-glyph-names.py — do not edit by hand.',
    f'// Unicode {unicodedata.unidata_version} names for every glyph in src/glyphs.js.',
    '',
    'export const GLYPH_NAMES = {',
]
for ch in glyphs:
    name = unicodedata.name(ch, '')
    if name:
        lines.append(f'  {json.dumps(ch, ensure_ascii=False)}: {json.dumps(name.capitalize())},')
lines.append('};')

with open('src/glyph-names.js', 'w', encoding='utf-8') as f:
    f.write('\n'.join(lines) + '\n')
print(f'{len(glyphs)} glyphs')
